package local.skyfamily;
import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.graphics.drawable.StateListDrawable;import android.view.Gravity;import android.view.View;import android.widget.*;import java.text.SimpleDateFormat;import java.util.*;
public class DashboardActivity extends MainActivity {
 final int bg=0xff0b1120,surface=0xff151f32,edge=0xff29364e,fg=0xfff0f5ff,muted=0xffa9b8cf,accent=0xff73dfcc;
 int dp(float n){return (int)(getResources().getDisplayMetrics().density*n+0.5f);}
 GradientDrawable shape(int color,int stroke,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
 android.graphics.drawable.Drawable press(int color){StateListDrawable d=new StateListDrawable();d.addState(new int[]{android.R.attr.state_pressed},shape(0xff2c4564,accent,18));d.addState(new int[]{},shape(color,edge,18));return d;}
 @Override void page(String title){
 if(web!=null){web.destroy();web=null;}
 getWindow().setFlags(android.view.WindowManager.LayoutParams.FLAG_FULLSCREEN,android.view.WindowManager.LayoutParams.FLAG_FULLSCREEN);
 LinearLayout shell=new LinearLayout(this);shell.setBackgroundColor(bg);shell.setOrientation(0);setContentView(shell);
 boolean wide=getResources().getConfiguration().screenWidthDp>=700;
 LinearLayout rail=new LinearLayout(this);rail.setOrientation(1);rail.setPadding(dp(10),dp(18),dp(10),dp(12));rail.setBackgroundColor(0xff10192a);
 shell.addView(rail,new LinearLayout.LayoutParams(dp(wide?142:82),-1));
 TextView brand=new TextView(this);brand.setText(wide?"SKY / FAMILY":"SKY");brand.setTextSize(wide?16:14);brand.setTextColor(accent);brand.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));brand.setPadding(dp(4),dp(8),0,dp(24));rail.addView(brand);
 nav(rail,"Home",()->home());nav(rail,"Apps",()->apps());nav(rail,"Create",()->drawing(false));nav(rail,"Notes",()->notes());nav(rail,"Explore",()->cameras());
 View spacer=new View(this);rail.addView(spacer,new LinearLayout.LayoutParams(1,0,1));nav(rail,"Settings",()->settings());
 LinearLayout content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(wide?26:14),dp(18),dp(wide?26:14),0);shell.addView(content,new LinearLayout.LayoutParams(0,-1,1));
 LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);content.addView(header,new LinearLayout.LayoutParams(-1,dp(60)));
 TextView name=new TextView(this);name.setText(title);name.setTextSize(wide?28:23);name.setTextColor(fg);name.setTypeface(Typeface.create("sans-serif-light",Typeface.NORMAL));header.addView(name,new LinearLayout.LayoutParams(0,-2,1));
 TextClock clock=new TextClock(this);clock.setFormat12Hour("h:mm a");clock.setFormat24Hour("HH:mm");clock.setTextSize(wide?25:18);clock.setTextColor(accent);header.addView(clock);
 ScrollView scroll=new ScrollView(this);content.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,dp(12),0,dp(26));scroll.addView(body);
 }
 void nav(LinearLayout rail,String name,Runnable r){TextView t=new TextView(this);t.setText(name);t.setTextSize(14);t.setTextColor(muted);t.setGravity(Gravity.CENTER);t.setBackground(press(surface));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.bottomMargin=dp(10);rail.addView(t,p);t.setOnClickListener(v->r.run());}
 @Override void text(String s){TextView t=new TextView(this);t.setText(s);t.setTextSize(17);t.setTextColor(muted);t.setPadding(dp(4),dp(10),dp(4),dp(16));t.setLineSpacing(dp(3),1);body.addView(t);}
 @Override void button(String s,Runnable r){TextView b=new TextView(this);b.setText(s+"   >");b.setTextColor(fg);b.setTextSize(17);b.setGravity(Gravity.CENTER_VERTICAL);b.setPadding(dp(20),dp(14),dp(16),dp(14));b.setBackground(press(surface));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);b.setMinHeight(dp(58));body.addView(b,p);b.setOnClickListener(v->r.run());}
 @Override EditText input(String hint,String value){EditText e=new EditText(this);e.setText(value);e.setHint(hint);e.setTextColor(fg);e.setHintTextColor(muted);e.setTextSize(18);e.setPadding(dp(16),dp(14),dp(16),dp(14));e.setBackground(shape(surface,edge,14));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);body.addView(e,p);return e;}
 void section(String value){TextView t=new TextView(this);t.setText(value.toUpperCase(Locale.getDefault()));t.setTextColor(muted);t.setTextSize(12);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(dp(4),dp(20),0,dp(12));body.addView(t);}
 LinearLayout grid;int count;int columns;
 void tile(String title,String subtitle,String mark,int color,Runnable action){if(count%columns==0){grid=new LinearLayout(this);grid.setOrientation(0);body.addView(grid);}LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);tile.setPadding(dp(18),dp(16),dp(18),dp(16));tile.setGravity(Gravity.CENTER_VERTICAL);tile.setBackground(press(surface));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(150),1);p.setMargins(dp(4),dp(4),dp(4),dp(4));grid.addView(tile,p);TextView icon=new TextView(this);icon.setText(mark);icon.setTextSize(15);icon.setTextColor(color);icon.setTypeface(Typeface.DEFAULT,Typeface.BOLD);tile.addView(icon);TextView name=new TextView(this);name.setText(title);name.setTextSize(20);name.setTextColor(fg);name.setPadding(0,dp(10),0,dp(5));tile.addView(name);TextView desc=new TextView(this);desc.setText(subtitle);desc.setTextSize(13);desc.setTextColor(muted);desc.setMaxLines(2);tile.addView(desc);tile.setContentDescription(title+". "+subtitle);tile.setFocusable(true);tile.setOnClickListener(v->action.run());count++;}
 void endgrid(){if(count%columns!=0)for(int i=count%columns;i<columns;i++)grid.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));count=0;}
 @Override void home(){page("Your family, together");columns=getResources().getConfiguration().screenWidthDp>=900?3:2;count=0;
 LinearLayout hero=new LinearLayout(this);hero.setOrientation(1);hero.setPadding(dp(24),dp(22),dp(24),dp(22));GradientDrawable gradient=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff183d50,0xff19283f});gradient.setCornerRadius(dp(22));hero.setBackground(gradient);body.addView(hero);
 TextView date=new TextView(this);date.setText(new SimpleDateFormat("EEEE, d MMMM",Locale.getDefault()).format(new Date()));date.setTextColor(accent);date.setTextSize(15);hero.addView(date);int hour=Calendar.getInstance().get(Calendar.HOUR_OF_DAY);TextView hello=new TextView(this);hello.setText(hour<12?"Good morning.":hour<18?"Good afternoon.":"Good evening.");hello.setTextSize(34);hello.setTextColor(fg);hello.setPadding(0,dp(8),0,dp(8));hero.addView(hello);TextView today=new TextView(this);String key=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());String events=get("event."+key);today.setText(events.isEmpty()?"A little space to learn, create and explore.":events);today.setTextSize(17);today.setTextColor(0xffd4e6ed);today.setMaxLines(3);hero.addView(today);hero.setOnClickListener(v->calendar());
 section("Everyday");tile("Calendar","Your plans, one day at a time","01 / PLAN",accent,()->calendar());tile("Daily notes","Ideas and little reminders","02 / WRITE",0xffffcf92,()->notes());tile("Apps","Open your installed favourites","03 / OPEN",0xffb8a5ff,()->apps());endgrid();
 section("Make room for imagination");tile("Drawing studio","Pick a colour. Make something.","STUDIO",0xfff2a4c6,()->drawing(false));tile("Colouring","A quiet moment of creativity","COLOUR",0xffffcf92,()->drawing(true));tile("Daily word","Five letters. Six chances.","PLAY",accent,()->puzzle());tile("Pocket creature","Feed, train and grow together","CARE",0xffb8a5ff,()->pet());endgrid();
 section("Your library");tile("Books & school","Open in an installed reader","READ",0xffffcf92,()->pick(false));tile("Local media","Open in an installed player","WATCH",0xfff2a4c6,()->pick(true));tile("Immich","Configured web connection","WEB PANEL",accent,()->panel("immich"));endgrid();
 section("A window to the world");tile("Space station","Configured ISS web page","WEB PANEL",0xffb8a5ff,()->panel("iss"));tile("Live cameras","Your saved places to explore","EXPLORE",accent,()->cameras());tile("News","Your configured news page","WEB PANEL",0xffffcf92,()->panel("news"));endgrid();text("Early prototype / Native Immich, screensaver, ISS telemetry and built-in ebook reader are not implemented.");
 }
}
